insert into items (competency_id, item_number, behaviour_text, asked_rater_groups, response_type, is_integrity_item, equivalent_item_id, design_note) values
  ((select id from competencies where number = 1 and variant = 'standard'), 1, 'Communicates through a mix of channels appropriate to the message, including face-to-face, written and team communication.', ARRAY['self', 'manager', 'peer', 'direct_report', 'other']::rater_group[], 'scale', false, null, null),
  ((select id from competencies where number = 1 and variant = 'standard'), 2, 'Holds regular, predictable check-ins or meetings with the team rather than relying on ad hoc contact.', ARRAY['self', 'manager', 'direct_report']::rater_group[], 'scale', false, null, 'Only line-managed staff can judge regularity.'),
  ((select id from competencies where number = 1 and variant = 'standard'), 3, 'Is genuinely accessible when staff need to raise something directly with them.', ARRAY['self', 'manager', 'peer', 'direct_report', 'other']::rater_group[], 'scale', false, null, null),
  ((select id from competencies where number = 1 and variant = 'standard'), 4, 'Explains the reasoning behind decisions, not just the decision itself.', ARRAY['self', 'manager', 'peer', 'direct_report', 'other']::rater_group[], 'scale', false, null, null),
