  ((select id from competencies where number = 1 and variant = 'standard'), 6, 'Actively listens to concerns or ideas raised by others and acts on them, or explains why action is not possible.', ARRAY['self', 'manager', 'peer', 'direct_report', 'other']::rater_group[], 'scale', false, null, 'Strongest item in the bank. Expect the widest self-versus-other gap.'),
