  ((select id from competencies where number = 1 and variant = 'standard'), 8, 'Checks in with individuals personally, not only through team-wide communication.', ARRAY['self', 'manager', 'direct_report', 'other']::rater_group[], 'scale', false, null, '''Others'' included: admin and support colleagues often are the omitted group.'),
  ((select id from competencies where number = 1 and variant = 'standard'), 9, 'Creates opportunities for people to ask questions, clarify expectations and challenge appropriately.', ARRAY['self', 'manager', 'peer', 'direct_report', 'other']::rater_group[], 'scale', false, null, null),
  ((select id from competencies where number = 1 and variant = 'standard'), 10, 'Follows up important messages or decisions to check that they have been understood and acted upon.', ARRAY['self', 'manager', 'direct_report', 'other']::rater_group[], 'scale', false, null, null),
